             `<path class="emo-steam" style="animation-delay:.4s" d="M2 -4 q2 -3 0 -6" stroke="${C.steam}" stroke-width="1.4" fill="none" stroke-linecap="round"/></g>` + hand(handX-6, handY+9);
    case "clipboard":
